-- Generated by scripts/seed-sql.ts from seed/scenarios.json.
-- Idempotent: safe to rerun. Do not edit by hand; edit scenarios.json and
-- regenerate with: npx tsx scripts/seed-sql.ts

SET XACT_ABORT ON;
BEGIN TRANSACTION;

MERGE dbo.Scenarios AS t
USING (VALUES
    (N'S01', 1, 1, N'implement-manage', N'Workspace and item security', N'The contractor request', N'An external contractor starts today to build Power BI reports on the gold lakehouse. Security policy: no access to bronze or silver data, no ability to modify items. Your workspace contains all three layers.', 0),
    (N'S01F', 1, 1, N'implement-manage', N'Workspace and item security', N'Follow-up: the deleted dataflow', N'The contractor accidentally deleted a silver dataflow while exploring the workspace. Downstream refreshes are failing.', 1),
    (N'S02', 1, 1, N'implement-manage', N'Lifecycle management: deployment pipelines', N'The hardcoded connection', N'You deploy from Test to Prod via a deployment pipeline. After deployment, the prod pipeline still ingests from the TEST SQL server. Business users are seeing test data in prod reports.', 0),
    (N'S03', 1, 2, N'implement-manage', N'Lifecycle management: Git integration', N'Two engineers, one workspace', N'Two engineers edited the same notebook directly in the shared dev workspace. One overwrote the other''s changes. Both are now blaming Fabric.', 0),
    (N'S04', 1, 2, N'implement-manage', N'Orchestration with parameters and dynamic expressions', N'Twelve copies of the same pipeline', N'A colleague built 12 nearly identical pipelines, one per source system. Source 13 arrives next week. Each change currently requires 12 manual edits.', 0),
    (N'S05', 1, 3, N'implement-manage', N'Security and governance: sensitivity and endorsement', N'The spreadsheet leak scare', N'Finance data marked Confidential was exported to Excel and mailed outside the company. Compliance asks what controls exist. Currently: none.', 0),
    (N'S06', 1, 3, N'ingest-transform', N'Choosing an ingestion pattern (batch)', N'Two hundred CSVs before coffee', N'A logistics partner drops ~200 small CSV files on an SFTP server every night. They must land in the bronze lakehouse by 06:00. No transformation needed at this stage. The junior engineer prefers low-code.', 0),
    (N'S07', 1, 4, N'ingest-transform', N'Mirroring and shortcuts', N'The Snowflake question', N'Sales operations runs on Snowflake. Analysts want near-real-time access in Fabric for cross-domain reporting. Nobody wants to build or maintain ETL for this.', 0),
    (N'S08', 1, 4, N'ingest-transform', N'Streaming ingestion and real-time processing', N'Trucks that talk', N'5,000 trucks emit GPS and temperature events every few seconds. Operations wants dashboards with time-windowed aggregations and sub-second query latency on the last 24 hours.', 0),
    (N'S08F', 1, 4, N'ingest-transform', N'Streaming ingestion and real-time processing', N'Follow-up: operations escalates', N'Operations reports the cold-chain dashboard lags 5+ minutes. A refrigerated trailer failure went unnoticed and a load spoiled.', 1),
    (N'S09', 1, 5, N'ingest-transform', N'Incremental loading', N'The nightly full load', N'A 400M-row order table is fully reloaded from the source ERP every night. The load window is about to be exceeded and the source DBA is complaining about extraction pressure. The table has a reliable ModifiedDate column.', 0),
    (N'S10', 1, 5, N'ingest-transform', N'Transformation engine selection', N'SCD2 at scale', N'Silver layer needs deduplication and Type 2 slowly changing dimension logic on a 500M-row customer history table. The team has both Power Query and PySpark skills.', 0),
    (N'S11', 1, 6, N'monitor-optimize', N'Capacity monitoring and throttling', N'Monday morning meltdown', N'09:00 Monday: report users get rejected queries. The capacity ran heavy background jobs all weekend. You need to diagnose before the CIO''s 10:00 call.', 0),
    (N'S11F', 1, 6, N'monitor-optimize', N'Capacity monitoring and throttling', N'Follow-up: the bill arrives', N'Finance flags the capacity cost increase. Metrics now show one unoptimized weekend Spark job caused 70% of the load. The bigger SKU is mostly idle.', 1),
    (N'S12', 1, 6, N'monitor-optimize', N'Direct Lake performance', N'The mysterious slowdown', N'A Direct Lake report was fast for months. Now visuals take seconds. Investigation shows the underlying table has accumulated tens of thousands of small parquet files, and queries fall back to DirectQuery.', 0),
    (N'S13', 1, 7, N'monitor-optimize', N'Spark performance optimization', N'The four-hour notebook', N'A silver transformation notebook grew from 20 minutes to 4 hours over six months. Spark UI shows massive shuffle, skewed partitions, and thousands of tiny input files from streaming ingestion.', 0),
    (N'S14', 1, 7, N'monitor-optimize', N'Error resolution in pipelines', N'The flaky API', N'A nightly pipeline pulls from a partner REST API that intermittently returns 429 (rate limited). The pipeline fails hard about twice a week and someone reruns it manually each morning.', 0),
    (N'S15', 1, 7, N'monitor-optimize', N'Monitoring and alerting', N'The silent stream', N'Last week the truck eventstream silently stopped for 6 hours; nobody noticed until a business user called. Management demands: never again. You need automated detection of data not arriving.', 0),
    (N'W2S01', 2, 1, N'implement-manage', N'Workspace settings: Spark pools and environments', N'The starter pool ceiling', N'Peak season starts Monday. The nightly transform notebook now handles six times the parcels and still runs on the workspace starter pool. Engineers report slow session starts and out-of-memory failures on the large joins.', 0),
    (N'W2S01F', 2, 1, N'implement-manage', N'Workspace settings: Spark pools and environments', N'Follow-up: the shared session crash', N'With high concurrency on, one engineer left a runaway cell running and it took the shared session down. Three unrelated notebooks died with it and the peak-season loads are behind.', 1),
    (N'W2S02', 2, 1, N'implement-manage', N'Workspace settings: domains', N'The domain nobody owns', N'The tenant has grown to 40 workspaces and nobody can find anything. Governance wants logistics data discoverable and separately governed from finance, without moving items between workspaces.', 0),
    (N'W2S03', 2, 2, N'implement-manage', N'Lifecycle management: database projects', N'Version control for the warehouse', N'The gold warehouse schema is changed by hand in production. Last week a column was dropped, a report broke, and nobody could say who did it or when. You need warehouse DDL under source control with a repeatable deploy.', 0),
    (N'W2S04', 2, 2, N'implement-manage', N'Security and governance: row and column level security', N'Three teams, one orders table', N'The gold orders table has to serve three audiences. Depot managers see only their own depot rows. Analysts see all rows but must not see the customer email column. Support agents need the email, but only the last four characters.', 0),
    (N'W2S04F', 2, 2, N'implement-manage', N'Security and governance: row and column level security', N'Follow-up: the copies disagree', N'Two weeks in, the three copies of the orders table report three different revenue totals. The Monday leadership meeting turned into an argument about whose number is right.', 1),
    (N'W2S05', 2, 3, N'implement-manage', N'Orchestration: schedules and event-based triggers', N'The file that arrives whenever it wants', N'A partner drops a manifest file into the landing lakehouse folder at some point between 02:00 and 07:00. Your pipeline runs on a 06:00 schedule, so roughly half the time it reprocesses yesterday.', 0),
    (N'W2S06', 2, 3, N'ingest-transform', N'Handling duplicate data', N'Forty million duplicate scans', N'Every parcel scanner retries on network failure, so bronze now holds the same scan event up to five times with identical scan ids and event timestamps. Silver row counts have stopped meaning anything.', 0),
    (N'W2S07', 2, 4, N'ingest-transform', N'Handling late-arriving data', N'Parcels that arrive yesterday', N'Handheld scanners sync when they find wifi, sometimes two days late. Your incremental load filters on scan timestamp greater than the last watermark, so those scans are silently dropped and daily volumes never reconcile.', 0),
    (N'W2S08', 2, 4, N'ingest-transform', N'Handling missing and late-arriving dimension data', N'The customer who does not exist yet', N'The order fact load fails nightly on the customer key lookup. New customers are created in the source CRM after the first order is placed, so the fact rows reference keys the dimension has never seen.', 0),
    (N'W2S09', 2, 5, N'ingest-transform', N'Loading a dimensional model: SCD type 1 and type 2', N'The depot that moved', N'Depot 14 relocated from Hamburg to Bremen. Finance needs last quarter shipments to still report as Hamburg. The same dimension also holds a phone number that has just been corrected after being wrong for years.', 0),
    (N'W2S09F', 2, 5, N'ingest-transform', N'Loading a dimensional model: SCD type 1 and type 2', N'Follow-up: the dimension that ate the model', N'Six weeks of type 2 on every column has turned a 400 row depot dimension into 90,000 rows. Direct Lake queries that join it have slowed noticeably and the semantic model refresh keeps climbing.', 1),
    (N'W2S10', 2, 5, N'ingest-transform', N'Streaming: windowing functions', N'Parcels per five minutes', N'Operations wants a live count of parcels scanned per depot in five-minute buckets, and alongside it a rolling one-hour average that updates every five minutes, both from the eventstream.', 0),
    (N'W2S11', 2, 6, N'monitor-optimize', N'Optimizing a lakehouse table', N'A million tiny files', N'The scan events Delta table is written every two minutes by a streaming job. It now holds 1.2 million files averaging 40 KB. Reads have gone from seconds to minutes and the Direct Lake model keeps falling back to DirectQuery.', 0),
    (N'W2S12', 2, 6, N'monitor-optimize', N'Optimizing a data warehouse', N'The warehouse that forgot', N'A gold warehouse query takes 40 seconds on its first run and 2 seconds after that. It is slow again after every nightly load, and the peak-season dashboards hit it at 08:00 sharp.', 0),
    (N'W2S13', 2, 6, N'monitor-optimize', N'Optimizing eventstreams and eventhouses', N'The stream falls behind', N'Peak volumes tripled the scan event rate. The eventstream input lag grows by minutes every hour and the eventhouse ingestion latency alert has been firing since 04:00.', 0),
    (N'W2S13F', 2, 6, N'monitor-optimize', N'Optimizing eventstreams and eventhouses', N'Follow-up: the same alert at 02:00', N'The restart bought four hours. The alert fired again overnight and this time the eventhouse dropped events when the ingestion buffer filled. Operations has lost two hours of scans.', 1),
    (N'W2S14', 2, 7, N'monitor-optimize', N'Identifying and resolving dataflow errors', N'The dataflow that failed at three percent', N'The Dataflow Gen2 loading partner reference data failed overnight with "The column DeliveryWindow of the table wasn''t found". The partner renamed a column in their export. Twelve downstream items are stale.', 0),
    (N'W2S15', 2, 7, N'monitor-optimize', N'Monitoring Fabric items', N'Who is watching what', N'Three people ask you three questions in ten minutes. Did last night pipeline run? Is the capacity throttled? Why is the semantic model showing yesterday data? You need one fast answer each.', 0),
    (N'W3S01', 3, 1, N'implement-manage', N'Workspace settings: data workflows', N'The inherited Airflow DAGs', N'The acquired Belgian carrier orchestrates 60 jobs with Apache Airflow DAGs their own team wrote. Leadership wants everything on Fabric by quarter end, and the Belgian engineers are threatening to leave if that means rewriting all of it as pipelines.', 0),
    (N'W3S02', 3, 1, N'implement-manage', N'Lifecycle management: Git branching strategy', N'Two teams, one main branch', N'Belgian and Nordwind engineers are now committing to the same workspace, connected to main. Yesterday a half-finished Belgian notebook was picked up by the deployment pipeline and shipped to test.', 0),
    (N'W3S03', 3, 2, N'implement-manage', N'Security and governance: OneLake data access roles', N'The auditors want one folder', N'External auditors need read access to a single folder of raw settlement files in the bronze lakehouse and nothing else. The same lakehouse holds HR extracts in a sibling folder.', 0),
    (N'W3S04', 3, 2, N'implement-manage', N'Security and governance: object-level security', N'The measure they must not see', N'The merged finance semantic model contains a Margin measure and a CostPrice column that the Belgian sales team must not see at all. Not blanked, not zeroed: they should not know the fields exist.', 0),
    (N'W3S05', 3, 3, N'implement-manage', N'Orchestration patterns: dependencies and retries', N'The chain that ran anyway', N'The merger load chain is ingest, then transform, then refresh the semantic model. Last night ingest failed on a transient gateway timeout, transform ran anyway on stale data, and finance opened a fully refreshed model full of wrong numbers.', 0),
    (N'W3S05F', 3, 3, N'implement-manage', N'Orchestration patterns: dependencies and retries', N'Follow-up: the guard that guarded nothing', N'The row-count check passed. Ingest failed after loading 90 percent of the rows, so the count looked plausible, transform ran, the model refreshed, and finance closed the month on incomplete data.', 1),
    (N'W3S06', 3, 3, N'ingest-transform', N'Metadata-driven ingestion', N'The merger two hundred tables', N'The Belgian SQL Server holds 214 tables that have to land in bronze. They differ in schema, watermark column and load frequency, and the list will keep changing as the merger progresses.', 0),
    (N'W3S07', 3, 4, N'ingest-transform', N'Choosing a streaming engine', N'Two ways to read the same stream', N'The Belgian fleet publishes GPS positions to an event hub at 50,000 events per second. Operations needs a five-second-latency live view, and analytics needs the same data enriched with a join to a 40 million row route dimension.', 0),
    (N'W3S08', 3, 4, N'ingest-transform', N'Denormalizing, grouping and aggregating', N'Sixty joins per report', N'The Belgian model arrived fully normalized: 60 tables in third normal form. Every merged report joins a dozen of them, Direct Lake queries are slow, and business users cannot find anything.', 0),
    (N'W3S09', 3, 5, N'ingest-transform', N'Choosing a transformation tool: KQL and eventhouse', N'Nine months of telemetry', N'Merged fleet telemetry lands at 900 GB a month. Operations queries the last seven days constantly with time-range and pattern searches. Finance queries the last nine months once a quarter for a cost model.', 0),
    (N'W3S09F', 3, 5, N'ingest-transform', N'Choosing a transformation tool: KQL and eventhouse', N'Follow-up: the eventhouse bill', N'The eventhouse now holds eight terabytes. The Capacity Metrics app shows it consuming more CU than every pipeline combined, and the CFO has circled the line in red.', 1),
    (N'W3S10', 3, 5, N'ingest-transform', N'Choosing an appropriate data store', N'Where does gold live', N'The merged gold layer has to serve three consumers: Power BI reports over a star schema, a Belgian application issuing ad-hoc T-SQL with multi-statement transactions, and data scientists running Spark notebooks.', 0),
    (N'W3S11', 3, 6, N'monitor-optimize', N'Identifying and resolving notebook errors', N'The notebook that dies at 03:00', N'The merged settlement notebook fails most nights with "Job aborted due to stage failure ... java.lang.OutOfMemoryError". It succeeds every time an engineer runs it by hand in the morning.', 0),
    (N'W3S12', 3, 6, N'monitor-optimize', N'Identifying and resolving T-SQL errors', N'Deadlocked at month end', N'Two merged month-end procedures write to the same warehouse tables in opposite order. One aborts on a conflict, leaves its work half applied, and the reconciliation report comes out wrong.', 0),
    (N'W3S13', 3, 6, N'monitor-optimize', N'Optimizing a pipeline', N'Six hours to copy', N'The nightly copy of the Belgian settlement tables takes six hours. The monitor shows one copy activity moving 400 GB from SQL Server through a gateway, one table at a time, at low throughput.', 0),
    (N'W3S13F', 3, 6, N'monitor-optimize', N'Optimizing a pipeline', N'Follow-up: which copy is right', N'The hourly copies overlap. Two runs wrote the same settlement rows with different values, the reconciliation now fails on 11,000 records, and nobody can say which run is authoritative.', 1),
    (N'W3S14', 3, 7, N'monitor-optimize', N'Monitoring a semantic model', N'The model that fell back', N'The merged finance model is Direct Lake. Since the merger load, morning queries are five times slower and users report timeouts. The report itself has not changed.', 0),
    (N'W3S15', 3, 7, N'monitor-optimize', N'Optimizing and evidencing query performance', N'The auditor last question', N'The auditor closing question: show that the merged platform month-end close finishes inside its four-hour window, and show that you can prove it again next month without doing this by hand.', 0)
) AS s (code, week, [day], domain, objective, title, incident, isFollowUp)
ON t.code = s.code
WHEN MATCHED THEN UPDATE SET
    week = s.week,
    [day] = s.[day],
    domain = s.domain,
    objective = s.objective,
    title = s.title,
    incident = s.incident,
    isFollowUp = s.isFollowUp
WHEN NOT MATCHED THEN INSERT (id, code, week, [day], domain, objective, title, incident, isFollowUp)
    VALUES (NEWID(), s.code, s.week, s.[day], s.domain, s.objective, s.title, s.incident, s.isFollowUp);

MERGE dbo.ScenarioOptions AS t
USING (
    SELECT sc.id AS scenario_id, v.optionKey, v.optionText, v.cuCost,
           v.slaDelta, v.correct, v.feedback, v.followUpCode
    FROM (VALUES
    (N'S01', N'A', N'Add the contractor as Viewer on the workspace', 0, -10, 0, N'Viewer grants read on ALL items in the workspace, including bronze and silver. Policy violated.', NULL),
    (N'S01', N'B', N'Share only the gold lakehouse item with Read and Build permission', 0, 5, 1, N'Item-level sharing scopes access to exactly one item. Build permission enables report creation on the semantic model without workspace membership.', NULL),
    (N'S01', N'C', N'Add the contractor as Member so they can build reports', 0, -20, 0, N'Member can edit and delete items across the workspace. Massive over-permissioning.', N'S01F'),
    (N'S01', N'D', N'Copy the gold tables into a new workspace every night with a pipeline', 15, -5, 0, N'Works, but burns CU on data duplication. A shortcut or item share achieves the same isolation for free.', NULL),
    (N'S01F', N'A', N'Restore from Git, revoke Member role, apply item-level sharing instead', 5, 0, 1, N'Git-synced workspaces let you restore deleted items from source control. Then fix the root cause: over-permissioning.', NULL),
    (N'S01F', N'B', N'Rebuild the dataflow manually and keep the Member role', 10, -10, 0, N'Rebuilding without source control wastes time and the root cause remains.', NULL),
    (N'S02', N'A', N'Edit the connection manually in prod after every deployment', 0, -10, 0, N'Manual post-deployment edits are error-prone and get forgotten. Exactly what just happened.', NULL),
    (N'S02', N'B', N'Configure deployment rules to swap data source parameters per stage', 0, 5, 1, N'Deployment rules (or parameterized connections via variable libraries) are the supported pattern for stage-specific values.', NULL),
    (N'S02', N'C', N'Maintain separate copies of the pipeline per environment, no deployment pipeline', 0, -15, 0, N'Drift guaranteed. You lose the whole point of lifecycle management.', NULL),
    (N'S03', N'A', N'Tell them to coordinate verbally before editing', 0, -5, 0, N'Process by hope. Does not scale beyond two people and fails the first busy week.', NULL),
    (N'S03', N'B', N'Give each engineer a feature-branch workspace, merge via pull requests', 5, 5, 1, N'The Git integration pattern: isolated workspaces per branch, PR review, then merge to the main branch that syncs the shared workspace.', NULL),
    (N'S03', N'C', N'Lock the workspace so only you can edit', 0, -10, 0, N'You just became the bottleneck for every change.', NULL),
    (N'S04', N'A', N'Build pipeline 13 the same way, refactor later', 5, -5, 0, N'Later never comes. Maintenance cost grows linearly with sources.', NULL),
    (N'S04', N'B', N'One metadata-driven pipeline: ForEach over a control table, parameters and dynamic expressions per source', 5, 10, 1, N'Parameterized orchestration with dynamic expressions is the exam-relevant and real-world pattern. Adding a source becomes a row in a table.', NULL),
    (N'S04', N'C', N'Move everything to one giant notebook', 10, -5, 0, N'Notebooks can orchestrate, but you lose pipeline-native monitoring, retries, and activity-level lineage without gaining anything here.', NULL),
    (N'S05', N'A', N'Disable export to Excel tenant-wide', 0, -10, 0, N'Blocks every legitimate analyst workflow in the company. Expect an uprising.', NULL),
    (N'S05', N'B', N'Apply sensitivity labels with protection so labels and encryption follow exported files', 0, 10, 1, N'Sensitivity labels persist through export, so downstream Office files inherit protection. Targeted control, minimal friction.', NULL),
    (N'S05', N'C', N'Send a policy reminder email', 0, -5, 0, N'Not a technical control. Compliance will ask again after the next incident.', NULL),
    (N'S06', N'A', N'Dataflow Gen2 reading all files with Power Query', 20, -5, 0, N'Dataflow Gen2 shines at transformation, but for raw file movement it is the most CU-expensive option here.', NULL),
    (N'S06', N'B', N'Pipeline Copy activity (or Copy job) from SFTP to lakehouse Files', 5, 5, 1, N'Plain data movement without transformation is exactly what Copy is for: cheap, fast, low-code.', NULL),
    (N'S06', N'C', N'PySpark notebook with an SFTP library', 10, 0, 0, N'Works, but custom code plus Spark startup overhead for a task a native connector handles out of the box.', NULL),
    (N'S07', N'A', N'Hourly pipeline copying changed tables into the lakehouse', 15, -5, 0, N'You just signed up to maintain the ETL nobody wanted, and ''near-real-time'' became ''hourly''.', NULL),
    (N'S07', N'B', N'Mirror the Snowflake database into Fabric', 5, 10, 1, N'Mirroring replicates changes continuously into OneLake as Delta, queryable across Fabric with no pipelines to maintain.', NULL),
    (N'S07', N'C', N'OneLake shortcut to Snowflake', 0, -5, 0, N'Shortcuts virtualize supported storage locations (ADLS, S3, GCS, Dataverse...). For a Snowflake database with continuous replication semantics, mirroring is the fit.', NULL),
    (N'S08', N'A', N'Eventstream into an Eventhouse (KQL database), query with KQL', 10, 10, 1, N'Eventhouse is purpose-built for high-frequency telemetry with low-latency time-series queries. KQL handles windowing natively.', NULL),
    (N'S08', N'B', N'Eventstream into a lakehouse Delta table, query with SQL endpoint', 10, -5, 0, N'Lands the data, but Delta plus SQL endpoint will not give sub-second latency on streaming telemetry at this frequency.', NULL),
    (N'S08', N'C', N'Micro-batch every 5 minutes with a scheduled pipeline', 15, -10, 0, N'5-minute batches fail the latency requirement outright, and frequent pipeline runs are CU-hungry.', N'S08F'),
    (N'S08F', N'A', N'Re-architect: Eventstream to Eventhouse, add an Activator alert on temperature threshold', 10, 5, 1, N'Real-time store plus event-driven alerting closes both the latency gap and the detection gap.', NULL),
    (N'S08F', N'B', N'Shrink the batch interval to 1 minute', 15, -5, 0, N'More CU, still not real-time, still no alerting.', NULL),
    (N'S09', N'A', N'Keep the full load but schedule it earlier', 20, -10, 0, N'Kicks the can. Volume grows, the window shrinks again, the DBA files a formal complaint.', NULL),
    (N'S09', N'B', N'Watermark-based incremental load on ModifiedDate, merge into the target', 5, 10, 1, N'A reliable modified-timestamp column is the textbook watermark case: extract only changed rows, MERGE into Delta.', NULL),
    (N'S09', N'C', N'Enable CDC on the source database', 10, 0, 0, N'CDC is the right tool when you need deletes and intermediate changes or there is no reliable watermark. Here it adds source-side complexity the watermark avoids.', NULL),
    (N'S10', N'A', N'Dataflow Gen2 with Power Query merge logic', 25, -10, 0, N'At 500M rows with SCD2 merge semantics, Dataflow Gen2 becomes slow and expensive. Wrong engine for the volume.', NULL),
    (N'S10', N'B', N'PySpark notebook with Delta MERGE for SCD2', 10, 10, 1, N'Spark plus Delta MERGE is built for exactly this: large-volume dedup and SCD2 with distributed compute.', NULL),
    (N'S10', N'C', N'T-SQL stored procedure in a Warehouse', 15, 0, 0, N'Viable in a warehouse-centric design, but the medallion lives in lakehouses here, and cross-item movement adds cost the notebook avoids.', NULL),
    (N'S11', N'A', N'Open the Capacity Metrics app: check utilization, smoothing, and which items are throttling', 0, 10, 1, N'Always diagnose first. The Capacity Metrics app shows interactive vs background consumption, smoothing effects, and the offending items.', NULL),
    (N'S11', N'B', N'Immediately scale up the capacity SKU', 20, -5, 0, N'Paying your way out before diagnosing. If one runaway job is the cause, you just doubled the bill for nothing.', N'S11F'),
    (N'S11', N'C', N'Restart the capacity', 5, -10, 0, N'Kills running jobs indiscriminately and destroys the evidence you need for the 10:00 call.', NULL),
    (N'S11F', N'A', N'Optimize the offending job, scale the SKU back down, set a surge protection threshold', 5, 5, 1, N'Fix the root cause, right-size, and add a guardrail so background surges cannot starve interactive users again.', NULL),
    (N'S11F', N'B', N'Keep the bigger SKU as headroom', 15, -5, 0, N'Paying permanently for one bad job. Finance will remember.', NULL),
    (N'S12', N'A', N'Run OPTIMIZE (with V-Order) on the table and schedule regular maintenance', 10, 10, 1, N'Small-file proliferation breaks Direct Lake guardrails and triggers DirectQuery fallback. Compaction with V-Order restores in-memory performance; scheduled maintenance prevents recurrence.', NULL),
    (N'S12', N'B', N'Switch the semantic model to Import mode', 15, -5, 0, N'Treats the symptom, adds refresh duplication and latency, and the underlying table stays unhealthy for every other consumer.', NULL),
    (N'S12', N'C', N'Disable DirectQuery fallback', 0, -10, 0, N'Now queries that exceed guardrails simply fail instead of running slowly. Users go from annoyed to blocked.', NULL),
    (N'S13', N'A', N'Increase the Spark pool size', 20, -5, 0, N'More executors shuffling the same skewed tiny files. Cost up, runtime barely down.', NULL),
    (N'S13', N'B', N'Fix the data layout: compact small files, address skew, verify partitioning strategy, then right-size compute', 10, 10, 1, N'Layout problems are solved at the layout level. Compaction and skew handling attack the root cause; only then is scaling a fair question.', NULL),
    (N'S13', N'C', N'Split the notebook into four notebooks running in parallel', 15, -5, 0, N'Four jobs now fight over the same skewed small-file mess, plus new orchestration complexity.', NULL),
    (N'S14', N'A', N'Configure retry with backoff on the activity, add failure-path notification', 0, 10, 1, N'429 is a transient, retryable condition. Activity-level retry with an interval absorbs it; the failure path alerts only when retries are exhausted.', NULL),
    (N'S14', N'B', N'Schedule the pipeline twice so the second run catches failures', 10, -5, 0, N'Doubles CU on good nights and still fails when both runs hit rate limits.', NULL),
    (N'S14', N'C', N'Wrap everything in a notebook with a try/except that ignores errors', 5, -15, 0, N'Silently swallowing errors means silently missing data. Worst possible outcome for trust in the platform.', NULL),
    (N'S15', N'A', N'Have an engineer check the Monitor hub every hour', 5, -10, 0, N'Human polling fails at night, on weekends, and during lunch. This is what event-driven alerting exists for.', NULL),
    (N'S15', N'B', N'Activator rule detecting absence of events beyond a threshold, alerting the on-call channel', 5, 10, 1, N'Activator monitors the stream itself and fires on conditions including missing data, turning a 6-hour blind spot into a minutes-level alert.', NULL),
    (N'S15', N'C', N'Daily row-count report emailed at 08:00', 5, -5, 0, N'Detection latency up to 24 hours. Better than nothing, far from ''never again''.', NULL),
    (N'W2S01', N'A', N'Define a custom Spark pool with larger nodes and autoscale in the workspace settings, and attach an environment with the required libraries', 10, 10, 1, N'Workspace Spark settings are where you define custom pools (node size, autoscale, executor range) and a default environment. Starter pools trade sizing control for fast session start; a known heavy workload is exactly the case for a custom pool.', NULL),
    (N'W2S01', N'B', N'Keep the starter pool and split the notebook into twelve smaller notebooks that run in sequence', 15, -5, 0, N'Twelve serial sessions cost more CU and more start-up time than one correctly sized pool, and the memory pressure just moves around.', NULL),
    (N'W2S01', N'C', N'Turn on high concurrency for the workspace and change nothing else', 0, -10, 0, N'High concurrency shares one session across notebooks to save start-up time. It adds no memory and no cores, so the out-of-memory failures stay.', N'W2S01F'),
    (N'W2S01', N'D', N'Ask finance to approve a bigger capacity SKU', 25, 0, 0, N'Buying capacity before sizing the pool is the expensive answer to a configuration question.', NULL),
    (N'W2S01F', N'A', N'Move the heavy batch job onto its own custom pool and keep high concurrency for the light interactive notebooks', 10, 5, 1, N'High concurrency is right for many small interactive workloads and wrong for one heavy batch job. Isolate the job that caused it rather than removing the setting everywhere.', NULL),
    (N'W2S01F', N'B', N'Disable high concurrency across the workspace and restart every notebook', 5, -5, 0, N'Throws away a real CU saving on the interactive work instead of isolating the single job that caused the crash.', NULL),
    (N'W2S02', N'A', N'Create Fabric domains, assign the logistics workspaces to a Logistics domain and delegate domain admins', 0, 10, 1, N'Domains group workspaces for discovery and delegated governance. Assignment is metadata, so nothing moves, and domain admins get their own settings and endorsement rules.', NULL),
    (N'W2S02', N'B', N'Rename every workspace with a "LOG - " prefix', 0, -5, 0, N'A naming convention is not governance. No delegated administration, no filtered discovery in the OneLake catalog.', NULL),
    (N'W2S02', N'C', N'Merge all logistics workspaces into one large workspace', 20, -15, 0, N'One workspace destroys the access boundary between teams and makes deployment pipelines unusable.', NULL),
    (N'W2S02', N'D', N'Stand up a separate tenant for logistics', 25, -20, 0, N'A second tenant duplicates capacity, identity and licensing to solve a discovery problem.', NULL),
    (N'W2S03', N'A', N'Export the warehouse as a SQL database project, commit it to Git, and deploy schema changes through the project', 5, 10, 1, N'Database projects capture warehouse DDL as code that can be diffed, reviewed and deployed. This is the supported lifecycle path for warehouse schema, alongside Git integration for the workspace items.', NULL),
    (N'W2S03', N'B', N'Take a nightly backup and restore it whenever something breaks', 15, -5, 0, N'Backups recover data, not intent. You still cannot review a schema change before it lands.', NULL),
    (N'W2S03', N'C', N'Revoke write access from everyone except yourself', 0, -10, 0, N'Now you are the bottleneck and the changes are still untracked.', NULL),
    (N'W2S03', N'D', N'Write a stored procedure that logs DDL changes to an audit table', 10, 0, 0, N'An audit trail after the fact. It tells you what broke; it does not let you review or roll back a change.', NULL),
    (N'W2S04', N'A', N'Apply row-level security for the depot filter, column-level security to deny the email column to analysts, and dynamic data masking for support', 10, 10, 1, N'Three different requirements, three different features. RLS filters rows with a predicate, CLS denies a column outright, and dynamic data masking rewrites the value at query time for unprivileged users.', NULL),
    (N'W2S04', N'B', N'Build three views, one per audience, and grant each team its own view', 10, 0, 0, N'Views hold until someone reaches the base table, and the depot filter still needs a per-user predicate. More objects to maintain for a weaker guarantee.', NULL),
    (N'W2S04', N'C', N'Copy the table three times, one per audience', 20, -15, 0, N'Three copies of a fact table burn storage and CU, and they drift apart within a week.', N'W2S04F'),
    (N'W2S04', N'D', N'Give every team full read access and circulate a policy document telling them what not to look at', 0, -20, 0, N'That is not access control, that is a hope.', NULL),
    (N'W2S04F', N'A', N'Collapse back to one table and enforce row-level security, column-level security and masking on it', 15, 5, 1, N'One table, one truth, security applied at query time. That is the entire point of row and column level security.', NULL),
    (N'W2S04F', N'B', N'Add a reconciliation pipeline that compares the three copies nightly and alerts on drift', 20, -10, 0, N'Building monitoring for a problem you could delete instead. The copies should not exist.', NULL),
    (N'W2S05', N'A', N'Replace the schedule with an event-based trigger on OneLake file creation for that folder', 5, 10, 1, N'Event-based triggers fire on OneLake item events, so the pipeline runs when the file lands rather than when the clock says it might have. No polling, no CU spent waiting.', NULL),
    (N'W2S05', N'B', N'Run the pipeline every fifteen minutes between 02:00 and 07:00 and exit early when there is no new file', 20, -5, 0, N'Twenty polling runs a night, most of them doing nothing, all of them costing CU. This is exactly what event triggers exist to avoid.', NULL),
    (N'W2S05', N'C', N'Move the schedule to 07:30 to be safe', 0, -5, 0, N'Later is not the same as reliable, and it pushes the whole downstream chain back ninety minutes.', NULL),
    (N'W2S05', N'D', N'Ask the partner to commit to a fixed delivery time', 0, -10, 0, N'Making your reliability depend on a third party keeping to a schedule is not a platform design.', NULL),
    (N'W2S06', N'A', N'Deduplicate on the natural key with a window function keeping the latest ingestion timestamp, then MERGE into silver', 10, 10, 1, N'ROW_NUMBER over the natural key ordered by ingestion time picks one winner deterministically, and MERGE keeps the silver load idempotent when the same batch is reprocessed.', NULL),
    (N'W2S06', N'B', N'Add DISTINCT to the silver query', 5, -5, 0, N'DISTINCT only removes rows identical in every column. Retries that differ by ingestion timestamp or source file survive it.', NULL),
    (N'W2S06', N'C', N'Ask the device team to stop retrying', 0, -15, 0, N'Retries are how the scanners survive a flaky depot network. Duplicates are yours to handle at ingest, not theirs to stop creating.', NULL),
    (N'W2S06', N'D', N'Delete bronze after each silver load so the duplicates cannot come back', 5, -20, 0, N'Deleting the raw layer removes your ability to reprocess and does nothing about the duplicates already in silver.', NULL),
    (N'W2S07', N'A', N'Watermark on ingestion time rather than event time, and reprocess a rolling three-day window into the affected partitions', 10, 10, 1, N'Event time says when it happened, ingestion time says when you could first have seen it. Watermarking on ingestion time plus a bounded reprocessing window catches late arrivals without a full reload.', NULL),
    (N'W2S07', N'B', N'Widen the watermark to reload everything from the last thirty days on every run', 25, -5, 0, N'Correct results at six times the CU. A three-day window covers the observed lateness; thirty days is a full reload in disguise.', NULL),
    (N'W2S07', N'C', N'Reject scans older than the watermark and log them to an error table', 5, -15, 0, N'You have built a permanent record of data you chose to lose. The daily volumes still do not reconcile.', NULL),
    (N'W2S07', N'D', N'Switch back to a full reload every night', 30, -10, 0, N'Solves lateness by abandoning incremental loading, and the load window was already the problem.', NULL),
    (N'W2S08', N'A', N'Insert an inferred member row for the unknown key and let the next dimension load fill in its attributes', 5, 10, 1, N'The inferred member pattern for late-arriving dimensions: create a placeholder carrying the business key, point the fact at it, and let the dimension load complete it later. The fact never fails and never loses a row.', NULL),
    (N'W2S08', N'B', N'Quarantine the failing rows and retry them the following night', 10, 0, 0, N'Workable, but revenue is under-reported for a day and quarantine tables grow into a second system nobody owns.', NULL),
    (N'W2S08', N'C', N'Point the orphaned orders at a single "Unknown customer" row', 5, -5, 0, N'The order is never reattached when the real customer appears, so customer-level analysis stays permanently wrong.', NULL),
    (N'W2S08', N'D', N'Drop the foreign key constraint', 0, -15, 0, N'The load stops failing and the model stops meaning anything.', NULL),
    (N'W2S09', N'A', N'Track the city as SCD type 2 with validity dates and a current flag, and overwrite the phone number as type 1', 10, 10, 1, N'The two attributes have different requirements. History matters for the city, so type 2 closes the old row and adds a new one. The phone number was simply wrong, so type 1 overwrites it and there is no history worth keeping.', NULL),
    (N'W2S09', N'B', N'Apply type 2 to the whole dimension so nothing is ever lost', 15, -5, 0, N'A new row every time a typo is fixed. The dimension grows for changes nobody will ever query.', N'W2S09F'),
    (N'W2S09', N'C', N'Apply type 1 to the whole dimension, it is simpler', 5, -15, 0, N'Last quarter shipments now report Bremen. The restated numbers will not match anything finance has published.', NULL),
    (N'W2S09', N'D', N'Keep a separate history table and join it when someone asks', 15, -10, 0, N'Rebuilding SCD type 2 by hand, badly, next to a dimension that could do it properly.', NULL),
    (N'W2S09F', N'A', N'Rebuild the dimension with type 2 on the attributes that need history and type 1 on the rest', 15, 5, 1, N'Type 2 is a per-attribute decision, not a per-table one. Restricting it to attributes with analytical meaning brings the row count straight back down.', NULL),
    (N'W2S09F', N'B', N'Filter the semantic model so it only loads current rows', 5, -10, 0, N'The historical rows still sit in the table and are still scanned by the load. You have discarded the history you paid to keep and kept the cost.', NULL),
    (N'W2S10', N'A', N'Use a tumbling window for the five-minute counts and a one-hour hopping window with a five-minute hop for the rolling average', 10, 10, 1, N'Tumbling windows are fixed and non-overlapping, so each event lands in exactly one bucket. Hopping windows overlap, and a one-hour window hopping every five minutes is precisely a rolling hourly average.', NULL),
    (N'W2S10', N'B', N'Use a sliding window for both', 10, -5, 0, N'Sliding windows emit whenever an event enters or leaves the window, not on a fixed cadence. Correct arithmetic, an output rate nobody asked for.', NULL),
    (N'W2S10', N'C', N'Use a session window with a five-minute gap', 10, -10, 0, N'Session windows group bursts of activity separated by idle gaps. A quiet depot would emit one window covering half the night.', NULL),
    (N'W2S10', N'D', N'Land the raw events in a lakehouse and let the report aggregate on refresh', 15, -15, 0, N'That is batch reporting with extra steps. Operations asked for live.', NULL),
    (N'W2S11', N'A', N'Schedule OPTIMIZE with V-Order on the table, then VACUUM to retire the superseded files', 10, 10, 1, N'OPTIMIZE compacts small files into large ones and V-Order writes them in the layout the Direct Lake engine reads best. VACUUM then removes the old files so storage and file listing stop growing.', NULL),
    (N'W2S11', N'B', N'Rewrite the whole table with a full overwrite every day', 25, -5, 0, N'Achieves compaction by rewriting every byte daily, and breaks any streaming reader following the table.', NULL),
    (N'W2S11', N'C', N'Raise the streaming trigger interval to one hour', 5, -10, 0, N'Fewer and larger files, at the cost of a one-hour latency on data operations needs live. It also does nothing about the 1.2 million files already written.', NULL),
    (N'W2S11', N'D', N'Move the table into a warehouse instead of a lakehouse', 20, -10, 0, N'Changing engine to avoid running a maintenance command. The small-file problem comes from the write pattern, not the storage choice.', NULL),
    (N'W2S12', N'A', N'Create and maintain statistics on the join and filter columns, and warm the cache with a query after the load', 5, 10, 1, N'The first run pays for statistics and a cold cache. Maintained statistics give the optimizer a plan without sampling at query time, and a post-load warm-up moves the remaining cost off the user 08:00.', NULL),
    (N'W2S12', N'B', N'Schedule the dashboards to refresh at 07:00 so users never hit the cold path', 10, 0, 0, N'Hides it for the dashboards and leaves every ad-hoc query on the slow path.', NULL),
    (N'W2S12', N'C', N'Add an index on every column of the fact table', 20, -15, 0, N'Fabric Warehouse does not work that way. There are no user-defined indexes to create; the engine relies on statistics and its own data layout.', NULL),
    (N'W2S12', N'D', N'Materialize the query result into a table after each load', 15, -5, 0, N'Fixes one query, leaves the warehouse cold for everything else, and adds another object to keep in sync.', NULL),
    (N'W2S13', N'A', N'Read the eventstream metrics to locate the bottleneck, then scale ingestion and tune the eventhouse batching policy toward throughput', 10, 10, 1, N'Read the metrics before changing anything. Growing input lag with a healthy downstream usually means ingestion throughput, and the eventhouse batching policy trades latency for throughput for exactly this case.', NULL),
    (N'W2S13', N'B', N'Restart the eventstream', 5, -10, 0, N'Clears the lag counter, not the cause. It returns within the hour and you have thrown away the diagnostic state.', N'W2S13F'),
    (N'W2S13', N'C', N'Drop the eventhouse retention policy to free up space', 5, -15, 0, N'Retention controls how long data is kept, not how fast it arrives. You have deleted history and fixed nothing.', NULL),
    (N'W2S13', N'D', N'Add a second eventstream reading the same source', 20, -5, 0, N'Two consumers of one source doubles the CU and usually duplicates the data downstream.', NULL),
    (N'W2S13F', N'A', N'Size ingestion for the peak rate properly, then backfill the missing window from the bronze landing table', 15, 5, 1, N'Two jobs: stop the loss by sizing ingestion for peak, then recover the gap from the durable copy. This is why raw events land in bronze before the stream.', NULL),
    (N'W2S13F', N'B', N'Restart it again and schedule an automatic restart every four hours', 10, -15, 0, N'Automating the workaround. Events keep dropping and now nobody looks at the alert.', NULL),
    (N'W2S14', N'A', N'Open the refresh history to find the failing step, make the dataflow tolerate the rename, and reload', 5, 10, 1, N'Dataflow refresh history points at the exact step and error message. Fixing the mapping and adding a column-existence check stops the next rename from breaking the load the same way.', NULL),
    (N'W2S14', N'B', N'Re-run the dataflow', 5, -10, 0, N'The file has not changed. It fails identically and you have spent CU proving it.', NULL),
    (N'W2S14', N'C', N'Disable staging to bypass the schema check', 5, -15, 0, N'Staging controls where intermediate results land, not schema validation. This changes performance and not the error.', NULL),
    (N'W2S14', N'D', N'Ask the partner to resend the file with the old column name', 0, -5, 0, N'Reasonable as a stopgap, useless as a design. The next rename breaks it again.', NULL),
    (N'W2S15', N'A', N'Monitor hub for the pipeline run, the Capacity Metrics app for throttling, and the semantic model refresh history for staleness', 0, 10, 1, N'Three questions, three purpose-built surfaces. Monitor hub is the cross-item run history, the Capacity Metrics app shows CU consumption and throttling over time, and refresh history is per item.', NULL),
    (N'W2S15', N'B', N'Query the SQL analytics endpoint to see whether the tables have new rows', 5, -5, 0, N'Tells you data is missing. It does not tell you which of the three layers failed, or why.', NULL),
    (N'W2S15', N'C', N'Build a custom monitoring pipeline that writes run status to a table', 25, -10, 0, N'Rebuilding the monitor hub with your own CU. Worth it for a bespoke SLA report, not for three questions the platform already answers.', NULL),
    (N'W2S15', N'D', N'Check the Fabric service health page', 0, -10, 0, N'That covers Microsoft-side outages. None of these three questions is an outage.', NULL),
    (N'W3S01', N'A', N'Enable data workflows on the workspace, run the existing DAGs there, and migrate selectively over time', 10, 10, 1, N'Fabric data workflows run Apache Airflow as a managed item, so proven DAGs move across without a rewrite. Migration to native pipelines then becomes a per-job decision instead of a condition of the merger.', NULL),
    (N'W3S01', N'B', N'Rewrite all 60 DAGs as Fabric pipelines before quarter end', 30, -15, 0, N'Sixty rewrites against a deadline, with the only people who understand them on their way out the door.', NULL),
    (N'W3S01', N'C', N'Leave Airflow running on the Belgian team own VMs outside Fabric', 15, -10, 0, N'Two orchestrators, two monitoring stacks and no lineage across the boundary. That is the merger problem, not the solution to it.', NULL),
    (N'W3S01', N'D', N'Trigger the Airflow DAGs from Fabric pipelines with a web activity', 15, -5, 0, N'Glue that hides the dependency. A failed DAG now shows as a successful pipeline in the monitor hub.', NULL),
    (N'W3S02', N'A', N'Give each team its own workspace branched out from main, and merge back through pull requests', 5, 10, 1, N'Branching out to a new workspace gives each team an isolated workspace bound to its own branch. Main stays deployable and review happens in the pull request rather than in production.', NULL),
    (N'W3S02', N'B', N'Agree that nobody commits until their work is finished', 0, -10, 0, N'A process agreement instead of an isolation boundary. It holds until the first busy Friday.', NULL),
    (N'W3S02', N'C', N'Put the two teams in two workspaces connected to two separate repositories', 10, -10, 0, N'Isolation with no merge path. The two codebases drift and there is no single main to deploy from.', NULL),
    (N'W3S02', N'D', N'Disconnect Git and go back to manual deployment', 5, -20, 0, N'Solving a branching problem by removing source control.', NULL),
    (N'W3S03', N'A', N'Create a OneLake data access role scoped to that folder and assign the auditors to it', 0, 10, 1, N'OneLake data access roles apply folder-level permissions inside a lakehouse, so a reader can be granted one folder and denied its siblings. It is the only mechanism that reaches this granularity without moving data.', NULL),
    (N'W3S03', N'B', N'Share the lakehouse item with read permission', 0, -20, 0, N'Item sharing is all or nothing for the lakehouse files. The auditors just received the HR extracts.', NULL),
    (N'W3S03', N'C', N'Copy the settlement folder into a new lakehouse for the auditors', 15, -5, 0, N'It works, and now you maintain a copy, a sync job and a second thing to secure, for a permission the platform can express directly.', NULL),
    (N'W3S03', N'D', N'Give the auditors the SQL analytics endpoint with a view over the settlement tables', 5, -5, 0, N'Fine for tabular access, but the auditors asked for the raw files and the endpoint does not expose them.', NULL),
    (N'W3S04', N'A', N'Apply object-level security to hide the measure and the column from that role in the semantic model', 5, 10, 1, N'Object-level security removes the object from the metadata for that role, so it is absent from the field list and from any query. Row-level security filters rows and column-level security denies access, but neither hides the existence of an object.', NULL),
    (N'W3S04', N'B', N'Use row-level security to filter out the margin rows', 5, -10, 0, N'RLS filters rows, and a measure is not a row. Margin would still be listed and would still evaluate over whatever rows remain.', NULL),
    (N'W3S04', N'C', N'Remove the measure from the model and build a second model for finance', 15, -5, 0, N'Two models to keep in sync so that one role cannot see one measure. Object-level security exists precisely so you do not do this.', NULL),
    (N'W3S04', N'D', N'Hide the field in the report', 0, -20, 0, N'Hidden in the report, fully available to anyone who connects to the model from Excel.', NULL),
    (N'W3S05', N'A', N'Wire the activity dependencies on success only and add a retry policy to the ingest activity', 5, 10, 1, N'Pipeline activity dependencies are per outcome. On completion runs regardless of result, which is what happened here; on success is what this chain needs. A retry policy absorbs the transient gateway timeout without waking anyone up.', NULL),
    (N'W3S05', N'B', N'Add a validation step in transform that checks the row count and exits when it looks stale', 10, 0, 0, N'A useful guard, but it is compensating for a dependency that is wired wrong one activity earlier.', N'W3S05F'),
    (N'W3S05', N'C', N'Split the chain into three separately scheduled pipelines with time gaps between them', 15, -15, 0, N'Replaces a dependency with a guess about duration. Under peak load the gap is too short and you are back here.', NULL),
    (N'W3S05', N'D', N'Refresh the semantic model by hand every morning after checking the logs', 10, -10, 0, N'A person as the dependency mechanism, every day, forever.', NULL),
    (N'W3S05F', N'A', N'Fix the dependency to on success, and keep the row-count check as a secondary guard', 10, 5, 1, N'Correctness comes from the dependency, not from the heuristic. Keep the check, but as a second line of defence rather than the first.', NULL),
    (N'W3S05F', N'B', N'Tighten the row-count threshold until a 90 percent load fails it', 5, -15, 0, N'Tuning a heuristic to catch one specific partial failure. The next one lands at 97 percent.', NULL),
    (N'W3S06', N'A', N'Build one parameterized pipeline driven by a control table of table names, watermarks and frequencies, invoked in a ForEach', 10, 10, 1, N'Metadata-driven ingestion: one pipeline, one control table, one row per source. Adding a table becomes an insert instead of a deployment, which is what you need when the list keeps moving.', NULL),
    (N'W3S06', N'B', N'Generate 214 pipelines with a script', 20, -10, 0, N'Generated sprawl. Every change to the pattern means regenerating and redeploying 214 items.', NULL),
    (N'W3S06', N'C', N'Use a single copy activity with a wildcard across all tables', 10, -15, 0, N'The tables differ in schema and watermark column. A wildcard copy cannot express per-table incremental logic.', NULL),
    (N'W3S06', N'D', N'Mirror the SQL Server database into Fabric and skip the pipelines', 15, 0, 0, N'A strong option for replication and worth considering, but it lands a mirror of the source schema rather than a curated bronze contract, and the per-table load frequency requirement disappears.', NULL),
    (N'W3S07', N'A', N'Use an eventstream into an eventhouse for the live view, and Spark structured streaming for the enrichment join', 15, 10, 1, N'Different requirements, different engines. Eventstream into an eventhouse is built for high-throughput ingest and sub-second query on recent data; a wide join against a large dimension is a Spark job. Neither engine is wrong, and each is wrong for one half.', NULL),
    (N'W3S07', N'B', N'Do both in Spark structured streaming', 20, -5, 0, N'Spark can do it, but a sub-five-second micro-batch trigger at this rate keeps a cluster hot around the clock for the live view.', NULL),
    (N'W3S07', N'C', N'Do both in the eventstream with a reference data lookup', 15, -10, 0, N'Eventstream lookups are meant for small reference sets. A 40 million row dimension is not one.', NULL),
    (N'W3S07', N'D', N'Land everything in a lakehouse and run a query every five seconds', 25, -15, 0, N'Micro-batching a lakehouse every five seconds recreates the small-file problem and still misses the latency target.', NULL),
    (N'W3S08', N'A', N'Denormalize into a star schema in gold, with conformed dimensions and a fact table at the grain the reports need', 15, 10, 1, N'Third normal form optimizes writes; analytics wants a star schema. Denormalizing into conformed dimensions and facts at a defined grain is what makes both the engine and the business users fast.', NULL),
    (N'W3S08', N'B', N'Create a view that joins the 60 tables and point the semantic model at it', 10, -10, 0, N'The joins still happen, once per query, and Direct Lake cannot benefit from a layout that does not exist on disk.', NULL),
    (N'W3S08', N'C', N'Pre-aggregate each report numbers into its own summary table', 20, -15, 0, N'Fast until the next question. Twelve summary tables and no model anyone can explore.', NULL),
    (N'W3S08', N'D', N'Keep the normalized model and train the business users on the joins', 5, -20, 0, N'Pushing a modelling problem onto everyone who will ever open the report.', NULL),
    (N'W3S09', N'A', N'Keep hot telemetry in an eventhouse queried with KQL, and tier the older months out to a lakehouse for the quarterly job', 10, 10, 1, N'KQL and the eventhouse are built for time-series and pattern queries over recent data. Nine-month scans read four times a year belong in cheap lakehouse storage, read by Spark or T-SQL when the question is actually asked.', NULL),
    (N'W3S09', N'B', N'Keep all nine months in the eventhouse', 25, -5, 0, N'You are paying eventhouse rates for nearly nine months of data that is read four times a year.', N'W3S09F'),
    (N'W3S09', N'C', N'Keep everything in a lakehouse and query it with Spark', 15, -10, 0, N'Correct for the quarterly job, far too slow for the pattern searches operations runs all day.', NULL),
    (N'W3S09', N'D', N'Keep everything in the warehouse and query it with T-SQL', 20, -15, 0, N'T-SQL over eight terabytes of time-series with pattern matching is the wrong engine for the dominant workload.', NULL),
    (N'W3S09F', N'A', N'Set retention and caching policies for the hot window, and export the cold months to the lakehouse before they age out', 10, 5, 1, N'Retention and caching policies are how an eventhouse stays affordable. Hot cache for what gets queried, retention for what must stay queryable, and the lakehouse for the rest.', NULL),
    (N'W3S09F', N'B', N'Delete everything older than 30 days', 5, -20, 0, N'The quarterly cost model needs nine months. You have just deleted the input to it.', NULL),
    (N'W3S10', N'A', N'Build gold in a warehouse for the transactional T-SQL consumer, and let Spark and Power BI read the same OneLake data', 10, 10, 1, N'The multi-statement transaction requirement is the deciding constraint, and only the warehouse offers it. Everything else reads the same Delta tables in OneLake, so Spark and Direct Lake are served without a copy.', NULL),
    (N'W3S10', N'B', N'Build gold in a lakehouse and give the application the SQL analytics endpoint', 10, -10, 0, N'The SQL analytics endpoint is read-only. The application multi-statement transactions have nowhere to go.', NULL),
    (N'W3S10', N'C', N'Build gold twice: a lakehouse for Spark and a warehouse for SQL', 20, -15, 0, N'Two golds, two loads and two versions of the truth, to avoid noticing that both engines read the same OneLake storage.', NULL),
    (N'W3S10', N'D', N'Build gold in an eventhouse so everything is fast', 20, -20, 0, N'An eventhouse is a time-series store. A merged finance star schema is not its workload.', NULL),
    (N'W3S11', N'A', N'Read the Spark application detail and driver logs to find the skewed stage, then fix the join and size the pool for it', 10, 10, 1, N'The Spark monitoring detail shows which stage failed and how its partitions were distributed. A job that passes on a quiet capacity and fails at 03:00 alongside everything else is usually skew plus contention, and the logs say which.', NULL),
    (N'W3S11', N'B', N'Raise the executor memory until it stops failing', 20, -5, 0, N'Sometimes works, always expensive, and it never tells you that one partition was doing 90 percent of the work.', NULL),
    (N'W3S11', N'C', N'Add a retry so it runs three times before failing', 15, -10, 0, N'Three out-of-memory failures instead of one, at three times the CU.', NULL),
    (N'W3S11', N'D', N'Move the notebook to 06:00 when the capacity is quiet', 5, -10, 0, N'It runs at 03:00 because downstream needs it by 06:00. Moving it moves the failure.', NULL),
    (N'W3S12', N'A', N'Wrap each procedure in an explicit transaction, order the writes consistently, and retry the loser on conflict', 10, 10, 1, N'Explicit transactions make a failed procedure leave nothing behind, consistent write ordering removes the cycle, and a retry handles the conflict that remains. The half-applied work is what turned this into a reporting error rather than an inconvenience.', NULL),
    (N'W3S12', N'B', N'Schedule the two procedures an hour apart', 5, -5, 0, N'Works until one of them runs long, and it does nothing about the half-applied writes when something else fails.', NULL),
    (N'W3S12', N'C', N'Wrap the procedure in a WHILE loop that retries on any error', 10, -10, 0, N'Retrying a non-transactional procedure re-applies work it has already committed.', NULL),
    (N'W3S12', N'D', N'Merge the two procedures into one so they cannot conflict', 15, 0, 0, N'Removes this specific conflict and creates one procedure that two teams now have to change together.', NULL),
    (N'W3S13', N'A', N'Partition the source reads, raise the degree of copy parallelism, and stage through the landing zone', 15, 10, 1, N'A single-threaded copy over a gateway is bounded by one connection. Source partitioning plus a higher degree of copy parallelism uses the gateway capacity, and staging decouples extract speed from the destination write.', NULL),
    (N'W3S13', N'B', N'Run the same copy activity every hour so it is always mostly done', 25, -10, 0, N'Six one-hour copies of overlapping data. More CU, the same throughput, and a new consistency problem.', N'W3S13F'),
    (N'W3S13', N'C', N'Compress the data at the source first', 10, -5, 0, N'Helps the wire and does nothing about a single-threaded read on a gateway that is not saturated.', NULL),
    (N'W3S13', N'D', N'Request a larger capacity', 25, -15, 0, N'The bottleneck is one connection through a gateway. More CU does not widen it.', NULL),
    (N'W3S13F', N'A', N'Stop the overlapping schedule, make the load idempotent with a MERGE on the business key, and reload the affected window', 15, 5, 1, N'Idempotency is what makes a load safe to repeat. A MERGE on the business key means a rerun converges instead of duplicating, and then the window can simply be reloaded.', NULL),
    (N'W3S13F', N'B', N'Keep the last write for each record and move on', 5, -15, 0, N'Last write wins by accident of scheduling, not by correctness. The reconciliation is still wrong, it is just quiet now.', NULL),
    (N'W3S14', N'A', N'Check the refresh history and the Direct Lake fallback state, then fix the guardrail the merged data is breaching', 10, 10, 1, N'Direct Lake falls back to DirectQuery when a guardrail is exceeded, for example a row count limit or a table it cannot read in Direct Lake mode. The refresh history and fallback indicators tell you which, and slower-but-working is the signature of fallback rather than failure.', NULL),
    (N'W3S14', N'B', N'Switch the model to import mode', 20, -5, 0, N'Trades the problem for a refresh window and a memory ceiling, without ever learning what broke Direct Lake.', NULL),
    (N'W3S14', N'C', N'Rebuild the report with fewer visuals', 10, -10, 0, N'The report did not change. The data underneath it did.', NULL),
    (N'W3S14', N'D', N'Move to a larger capacity SKU', 25, -10, 0, N'A larger SKU raises the Direct Lake guardrails, so it might mask this. An expensive way to avoid reading the fallback reason.', NULL),
    (N'W3S15', N'A', N'Instrument the close as a monitored pipeline and report the trend of run duration and CU per stage from the Capacity Metrics app', 10, 10, 1, N'The question is not whether it is fast today, it is whether you can show it stays fast. Monitor hub gives run history per activity, the Capacity Metrics app gives CU per item over time, and together they are a repeatable answer rather than a screenshot.', NULL),
    (N'W3S15', N'B', N'Run the close now, time it with a stopwatch, and send the auditor a screenshot', 0, -15, 0, N'Answers this month and guarantees an identical afternoon next month.', NULL),
    (N'W3S15', N'C', N'Export every run log to a lakehouse and build a custom report on it', 25, 0, 0, N'A defensible answer at a high build cost, when the platform already emits both halves of it.', NULL),
    (N'W3S15', N'D', N'Tell the auditor the close has never missed its window', 0, -20, 0, N'An assertion is not evidence, and the auditor asked for evidence.', NULL)
    ) AS v (scenarioCode, optionKey, optionText, cuCost, slaDelta, correct, feedback, followUpCode)
    INNER JOIN dbo.Scenarios sc ON sc.code = v.scenarioCode
) AS s
ON t.scenario_id = s.scenario_id AND t.optionKey = s.optionKey
WHEN MATCHED THEN UPDATE SET
    optionText = s.optionText,
    cuCost = s.cuCost,
    slaDelta = s.slaDelta,
    correct = s.correct,
    feedback = s.feedback,
    followUpCode = s.followUpCode
WHEN NOT MATCHED THEN INSERT (id, scenario_id, optionKey, optionText, cuCost, slaDelta, correct, feedback, followUpCode)
    VALUES (NEWID(), s.scenario_id, s.optionKey, s.optionText, s.cuCost, s.slaDelta, s.correct, s.feedback, s.followUpCode)
WHEN NOT MATCHED BY SOURCE THEN DELETE;

COMMIT TRANSACTION;

SELECT (SELECT COUNT(*) FROM dbo.Scenarios) AS scenarios,
       (SELECT COUNT(*) FROM dbo.ScenarioOptions) AS options;
